import {stages} from './model.js?v=20261017-5';
const $=s=>document.querySelector(s);
export function setupPolish(){
 const curve=document.createElement('section');curve.className='hero-curve';curve.setAttribute('aria-label','四工况安全系数与三维模型联动');
 const xs=[36,158,280,402],y=v=>105-v*45;
 curve.innerHTML=`<div class="hero-curve-heading"><strong>四个工况，一条稳定性曲线</strong><span>Fₛ = R / T</span></div><svg viewBox="0 0 438 118" aria-hidden="true"><defs><linearGradient id="hero-curve-area" x2="0" y2="1"><stop stop-color="#9bbca1" stop-opacity=".23"/><stop offset="1" stop-color="#9bbca1" stop-opacity="0"/></linearGradient><linearGradient id="hero-curve-stroke"><stop stop-color="#9ccbb2"/><stop offset=".6" stop-color="#e4b47a"/><stop offset="1" stop-color="#d4856b"/></linearGradient></defs><path d="M22,${y(1)}H416" stroke="#d3af7c" stroke-opacity=".4" stroke-dasharray="3 5"/><text x="20" y="${y(1)-7}">Fₛ = 1</text><path d="M${xs.map((x,i)=>`${x},${y(+stages[i].value)}`).join('L')}V112H36Z" fill="url(#hero-curve-area)"/><path class="hero-curve-line" d="M${xs.map((x,i)=>`${x},${y(+stages[i].value)}`).join('L')}" fill="none" stroke="url(#hero-curve-stroke)" stroke-width="2.5"/>${xs.map((x,i)=>`<g data-hero-dot="${i}"><circle class="hero-dot-halo" cx="${x}" cy="${y(+stages[i].value)}" r="10"/><circle cx="${x}" cy="${y(+stages[i].value)}" r="4" fill="${i<2?'#a2cdb2':'#dda57b'}"/></g>`).join('')}</svg><div class="hero-case-buttons" role="group" aria-label="点选工况，三维剖面同步切换">${stages.map((s,i)=>`<button type="button" data-hero-stage="${i}" aria-pressed="${i===0}"><small>0${i+1} · ${s.short}</small><strong>${s.value}<span>↗</span></strong></button>`).join('')}</div><p><span class="hero-touch-dot" aria-hidden="true"></span>点选工况，右侧三维剖面同步变化<span class="hero-curve-mobile">；手机上模型位于下方</span></p>`;
 $('.hero-actions').after(curve);
 curve.addEventListener('click',e=>{const button=e.target.closest('[data-hero-stage]');if(button)$(`.stage-tabs button[data-stage="${button.dataset.heroStage}"]`).click();});
 curve.querySelector(':scope>p').innerHTML='<span class="hero-touch-dot" aria-hidden="true"></span>点选工况，三维剖面同步变化<button type="button" class="hero-return-model">查看上方模型 ↑</button>';
 curve.querySelector('.hero-return-model').addEventListener('click',()=>$('.hero-model').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'}));
 const update=stage=>{curve.querySelectorAll('[data-hero-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.heroStage===stage)));curve.querySelectorAll('[data-hero-dot]').forEach(dot=>dot.classList.toggle('is-current',+dot.dataset.heroDot===stage));};update(0);document.addEventListener('lab-calculated',e=>update(e.detail.stage));
 const panel=$('.hero-model'),placeholder=document.createComment('hero-model-home');panel.before(placeholder);
 const zoom=document.createElement('button');zoom.type='button';zoom.id='hero-model-zoom';zoom.className='model-expand';zoom.textContent='展开模型 ↗';$('.model-workspace-label').append(zoom);
 const dialog=document.createElement('dialog');dialog.className='hero-model-dialog';dialog.id='hero-model-dialog';dialog.setAttribute('aria-label','交互工程剖面大图');dialog.innerHTML='<button class="close-dialog" type="button" aria-label="关闭模型大图">×</button>';document.body.append(dialog);
 zoom.addEventListener('click',()=>{if(dialog.open){dialog.close();return;}dialog.append(panel);zoom.textContent='恢复页面视图 ↙';dialog.showModal();});dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{placeholder.after(panel);zoom.textContent='展开模型 ↗';zoom.focus({preventScroll:true});});
 const mobile=matchMedia('(max-width:760px)'),movable=[curve,$('.hero .author'),$('.hero-engineering')],homes=movable.map(el=>{const mark=document.createComment('hero-copy-position');el.before(mark);return mark;});
 const arrange=()=>{if(mobile.matches)(dialog.open?placeholder:panel).after(...movable);else movable.forEach((el,i)=>homes[i].after(el));};mobile.addEventListener('change',arrange);arrange();
 const progress=document.createElement('div');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');progress.innerHTML='<i></i>';document.body.append(progress);let frame=null;
 const paint=()=>{frame=null;const range=document.documentElement.scrollHeight-innerHeight;progress.firstElementChild.style.transform=`scaleX(${range>0?Math.min(1,scrollY/range):0})`;};addEventListener('scroll',()=>{if(frame===null)frame=requestAnimationFrame(paint);},{passive:true});addEventListener('resize',paint);paint();
 if(!matchMedia('(prefers-reduced-motion:reduce)').matches){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('section-arrived');observer.unobserve(entry.target);}},{threshold:.15});document.querySelectorAll('.section>.section-heading,.section>.section-label').forEach(e=>observer.observe(e));}
}
